// Kukicha Standard Library - Errors
// Error wrapping and dual-message helpers that complement
// Kukicha's built-in `error "message"` syntax.
//
// Examples:
//
//	err := errors.Wrap(originalErr, "loading config")
//	# err.Error() == "loading config: <original message>"
//
//	# Safe to return to end users while logging details internally
//	return errors.NewPublic("pg: connection refused to 10.0.0.1", "database unavailable")
